window.STORY_CHAPTERS=window.STORY_CHAPTERS||{};window.STORY_CHAPTERS["92cf4423-279a-5656-a6de-fe36f39c0f04"]={"id":"92cf4423-279a-5656-a6de-fe36f39c0f04","scenes":[{"id":"0ec1325d-ecff-5169-9304-3343c676305b","name":"Утро в Peugeot","backgroundId":"3d80f14b-22c0-57d7-8196-2678794c91d0","characterId":"","emotionId":"","text":"Зоя проснулась от осторожного стука в окно. Снаружи стоял дворник с метлой.","italic":false,"lines":[{"id":"310b0a7a-31b1-5dcc-a06a-f701130e2001","text":"Я здесь не ночевала. Я очень долго размышляла с закрытыми глазами.","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","italic":false},{"id":"1c356391-6826-5a54-86fb-4d00a52d0c57","text":"Дворник посмотрел на подушку на заднем сиденье, но спорить не стал.","characterId":"","emotionId":"","italic":false},{"id":"6670a8b7-f40d-56d3-b8a7-d6b36e10b14a","text":"В телефоне ждало сообщение от женщины, чей план Зоя поддержала накануне.","characterId":"","emotionId":"","italic":false}],"route":{"next":"","statId":"11bd0163-2973-589d-b646-1502801c746a","operator":">=","value":1,"yes":"73a9e27c-f2e7-5a9d-892c-0167404c88fc","no":"85bd8dfe-beb9-5943-9709-1a7925b14472"},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[]},{"id":"73a9e27c-f2e7-5a9d-892c-0167404c88fc","name":"Сообщение С. С.","backgroundId":"3d80f14b-22c0-57d7-8196-2678794c91d0","characterId":"","emotionId":"","text":"«В девять будь возле старого административного здания. Встреча с человеком, который знает о магазине больше, чем должен. Не опаздывай. С. С.»","italic":false,"lines":[{"id":"21b12a54-9662-5d44-81e6-a0f89c6c568a","text":"Мне нравится, когда утро начинается без угроз. Жаль, сегодня не тот случай.","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","italic":false}],"route":{"next":"92f3293b-0e54-5626-b8e2-0c23091f0126","statId":"","operator":">=","value":0,"yes":"","no":""},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[]},{"id":"85bd8dfe-beb9-5943-9709-1a7925b14472","name":"Сообщение Натальи","backgroundId":"3d80f14b-22c0-57d7-8196-2678794c91d0","characterId":"","emotionId":"","text":"«Приходи к служебному входу Санты. Познакомлю с людьми, от которых зависит больше, чем думает руководство. Наталья». ","italic":false,"lines":[{"id":"e557e6d1-0779-56e5-bdf5-0e6bc346d023","text":"Служебный вход — значит, уже почти должность. Осталось выяснить, какая.","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","italic":false}],"route":{"next":"92f3293b-0e54-5626-b8e2-0c23091f0126","statId":"","operator":">=","value":0,"yes":"","no":""},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[]},{"id":"92f3293b-0e54-5626-b8e2-0c23091f0126","name":"Заправка перед дорогой","backgroundId":"c4404365-1741-57fd-91bd-17d65297ff03","characterId":"","emotionId":"","text":"Перед поездкой Зоя посмотрела на остаток звёздочек и топлива. Можно заправиться или выбрать бесплатный автобус.","italic":false,"lines":[],"route":{"next":"","statId":"","operator":">=","value":0,"yes":"","no":""},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[{"id":"f2fec35c-e3d4-5954-9b70-64aa556d13cf","text":"Заправить 2 единицы за 5 ✦","nextSceneId":"4fc8440a-2e89-54af-91e4-3973cf192521","money":0,"cost":5,"statId":"","statChange":0,"extraStatId":"","extraStatChange":0,"important":false,"fuelCost":0,"fuelGain":2,"condition":{"statId":"","operator":">=","value":0,"yes":"","no":""},"requirement":{"statId":"","operator":">=","value":0}},{"id":"31594e69-e422-5f79-9319-429eb8b041d3","text":"Заправить 5 единиц за 10 ✦","nextSceneId":"d37fc87b-2a66-599c-a4c1-35ee5c73f02e","money":0,"cost":10,"statId":"","statChange":0,"extraStatId":"","extraStatChange":0,"important":false,"fuelCost":0,"fuelGain":5,"condition":{"statId":"","operator":">=","value":0,"yes":"","no":""},"requirement":{"statId":"","operator":">=","value":0}},{"id":"437d884c-d319-5d5e-a243-49dc2fc9caec","text":"Не заправляться","nextSceneId":"693f4514-d587-53ae-8257-5b92651953ba","money":0,"cost":0,"statId":"","statChange":0,"extraStatId":"","extraStatChange":0,"important":false,"fuelCost":0,"fuelGain":0,"condition":{"statId":"","operator":">=","value":0,"yes":"","no":""},"requirement":{"statId":"","operator":">=","value":0}}]},{"id":"4fc8440a-2e89-54af-91e4-3973cf192521","name":"Немного топлива","backgroundId":"c4404365-1741-57fd-91bd-17d65297ff03","characterId":"","emotionId":"","text":"Зоя заплатила за небольшую заправку и убрала чек в карман.","italic":false,"lines":[{"id":"0e52b1d1-3f82-5638-bf9b-dcb94e58570f","text":"Сегодня главное — добраться. На остальное ещё заработаем.","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","italic":false}],"route":{"next":"ef2f8029-f2dd-512f-b95b-5fbad0ffc796","statId":"","operator":">=","value":0,"yes":"","no":""},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[]},{"id":"d37fc87b-2a66-599c-a4c1-35ee5c73f02e","name":"Запас на день","backgroundId":"c4404365-1741-57fd-91bd-17d65297ff03","characterId":"","emotionId":"","text":"Зоя решила потратить больше сейчас и оставить запас на следующие поездки.","italic":false,"lines":[{"id":"436810f5-e6a1-5bf1-8081-121496aaeafd","text":"Peugeot, мы с тобой теперь и транспорт, и квартира. Старайся не подводить.","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","italic":false}],"route":{"next":"ef2f8029-f2dd-512f-b95b-5fbad0ffc796","statId":"","operator":">=","value":0,"yes":"","no":""},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[]},{"id":"693f4514-d587-53ae-8257-5b92651953ba","name":"Сохранить деньги","backgroundId":"c4404365-1741-57fd-91bd-17d65297ff03","characterId":"","emotionId":"","text":"Зоя решила сохранить деньги. При необходимости она сможет ехать автобусом.","italic":false,"lines":[{"id":"4aeff8fe-a6cf-574f-95d5-2281608943c3","text":"Раз уж мы строим большой план, начнём с маленькой экономии.","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","italic":false}],"route":{"next":"ef2f8029-f2dd-512f-b95b-5fbad0ffc796","statId":"","operator":">=","value":0,"yes":"","no":""},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[]},{"id":"ef2f8029-f2dd-512f-b95b-5fbad0ffc796","name":"Дорога","backgroundId":"c4404365-1741-57fd-91bd-17d65297ff03","characterId":"","emotionId":"","text":"Зое нужно решить, как добраться на встречу. Расход топлива и стоимость видны заранее.","italic":false,"lines":[],"route":{"next":"","statId":"","operator":">=","value":0,"yes":"","no":""},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[{"id":"9598abd5-64bc-503f-9e8e-a4565a6c701f","text":"На Peugeot · потратить 1 топливо","nextSceneId":"aff55648-c5f4-56b9-bf31-9b0a5ae80a5a","money":0,"cost":0,"statId":"0c14bd21-7b6e-5d6c-9ffc-ef28f92c1783","statChange":1,"extraStatId":"","extraStatChange":0,"important":false,"fuelCost":1,"fuelGain":0,"condition":{"statId":"","operator":">=","value":0,"yes":"","no":""},"requirement":{"statId":"","operator":">=","value":0}},{"id":"1b6d75b3-b3dd-5b1e-ae50-70cdede050ff","text":"На автобусе · бесплатно","nextSceneId":"85d1e298-4457-55bd-8a63-36a7d0b09cf2","money":0,"cost":0,"statId":"","statChange":0,"extraStatId":"","extraStatChange":0,"important":false,"fuelCost":0,"fuelGain":0,"condition":{"statId":"","operator":">=","value":0,"yes":"","no":""},"requirement":{"statId":"","operator":">=","value":0}},{"id":"abb54c16-9ff7-5ea5-ad0b-1eb953428630","text":"На такси · 5 ✦","nextSceneId":"0fabce95-d131-51d1-a1d2-d591d7a1789b","money":0,"cost":5,"statId":"0c14bd21-7b6e-5d6c-9ffc-ef28f92c1783","statChange":1,"extraStatId":"","extraStatChange":0,"important":false,"fuelCost":0,"fuelGain":0,"condition":{"statId":"","operator":">=","value":0,"yes":"","no":""},"requirement":{"statId":"","operator":">=","value":0}}]},{"id":"aff55648-c5f4-56b9-bf31-9b0a5ae80a5a","name":"Поездка на Peugeot","backgroundId":"08eee936-c9e9-4abc-b768-70914bb2b1fe","characterId":"","emotionId":"","text":"Машина завелась не с первого раза. Зоя погладила руль.","italic":false,"lines":[{"id":"71135c83-6c4a-5ae8-a301-fac2cd234c27","text":"Только не сегодня. У нас с тобой важная карьера.","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","italic":false},{"id":"436ef742-0af0-54b8-825e-d4f826cf0219","text":"Она добралась вовремя и нашла нужный адрес.","characterId":"","emotionId":"","italic":false}],"route":{"next":"79ccf062-216a-54e2-a584-bb0e28de37e7","statId":"","operator":">=","value":0,"yes":"","no":""},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[]},{"id":"85d1e298-4457-55bd-8a63-36a7d0b09cf2","name":"Долгая дорога","backgroundId":"ab5af97c-9f85-5a82-9d93-1f1292157b05","characterId":"","emotionId":"","text":"Автобус снова задержался на перекрёстке. Зоя посмотрела на часы и спрятала телефон.","italic":false,"lines":[{"id":"9b87ba84-97f2-5fe4-831a-d4a656ef085b","text":"Главное, что я всё ещё успеваю стать кем-нибудь важным. Когда-нибудь.","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","italic":false},{"id":"3c316cfd-b781-5fa1-a938-2a94f6de7944","text":"К месту встречи она подошла позже назначенного.","characterId":"","emotionId":"","italic":false}],"route":{"next":"79ccf062-216a-54e2-a584-bb0e28de37e7","statId":"","operator":">=","value":0,"yes":"","no":""},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[]},{"id":"0fabce95-d131-51d1-a1d2-d591d7a1789b","name":"Такси до встречи","backgroundId":"08eee936-c9e9-4abc-b768-70914bb2b1fe","characterId":"","emotionId":"","text":"Водитель включил радио, и всю дорогу диктор обсуждал новости мясокомбината.","italic":false,"lines":[{"id":"e7227a4c-4ea0-59c8-b67c-a7b1209bea4d","text":"Можно потише? Эта история уже однажды испортила мне день.","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","italic":false},{"id":"2aa5050f-7c03-59ab-866b-317b298d8849","text":"Такси остановилось у нужного адреса. Зоя расплатилась и вышла.","characterId":"","emotionId":"","italic":false}],"route":{"next":"79ccf062-216a-54e2-a584-bb0e28de37e7","statId":"","operator":">=","value":0,"yes":"","no":""},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[]},{"id":"79ccf062-216a-54e2-a584-bb0e28de37e7","name":"Выбранный путь","backgroundId":"08eee936-c9e9-4abc-b768-70914bb2b1fe","characterId":"","emotionId":"","text":"Вчерашнее решение определило, с кого начнётся подготовка к большому кушу.","italic":false,"lines":[],"route":{"next":"","statId":"11bd0163-2973-589d-b646-1502801c746a","operator":">=","value":1,"yes":"8972c629-bf98-5c79-8c71-4db6373cc212","no":"b2053e4d-79fe-515e-a0d6-28f215244461"},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[]},{"id":"8972c629-bf98-5c79-8c71-4db6373cc212","name":"У административного здания","backgroundId":"ae067d37-2695-5239-9276-39224dc00643","characterId":"","emotionId":"","text":"С. С. ждёт возле входа. Как прошла дорога?","italic":false,"lines":[],"route":{"next":"","statId":"0c14bd21-7b6e-5d6c-9ffc-ef28f92c1783","operator":">=","value":1,"yes":"e2fdede2-bda2-5b2e-a3c0-e4a6a53a0c2d","no":"3034ef29-e86b-55cd-9356-7dac67270629"},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[]},{"id":"e2fdede2-bda2-5b2e-a3c0-e4a6a53a0c2d","name":"Неизвестный у входа","backgroundId":"ae067d37-2695-5239-9276-39224dc00643","characterId":"","emotionId":"","text":"Зоя замечает мужчину, который, увидев С. С., торопливо уходит к лестнице.","italic":false,"lines":[{"id":"d1173da4-d784-52bf-abf0-f51c85f1d1b3","text":"Похоже, нас уже заметили.","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","italic":false}],"route":{"next":"bd5e70f8-ead7-5386-8186-67bbf8639c42","statId":"","operator":">=","value":0,"yes":"","no":""},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[]},{"id":"3034ef29-e86b-55cd-9356-7dac67270629","name":"Опоздание на встречу","backgroundId":"ae067d37-2695-5239-9276-39224dc00643","characterId":"c15323c4-79bc-4b5d-868f-fff59ea61a0b","emotionId":"fdf2ff59-2e09-59fc-a1ba-d3f557781c3a","text":"Наш собеседник решил, что мы не придём. Убедим его в обратном.","italic":false,"lines":[{"id":"3bf74ffc-8d70-5793-9eeb-78c24a00153e","text":"В следующий раз автобус будет двигаться по моему расписанию.","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","italic":false}],"route":{"next":"bd5e70f8-ead7-5386-8186-67bbf8639c42","statId":"","operator":">=","value":0,"yes":"","no":""},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[]},{"id":"bd5e70f8-ead7-5386-8186-67bbf8639c42","name":"С. С. ждёт","backgroundId":"ae067d37-2695-5239-9276-39224dc00643","characterId":"c15323c4-79bc-4b5d-868f-fff59ea61a0b","emotionId":"fdf2ff59-2e09-59fc-a1ba-d3f557781c3a","text":"Наш собеседник не любит опозданий, ненужных вопросов и меня.","italic":false,"lines":[{"id":"c6ee5d05-0d61-5770-ba59-8c467a7c53b1","text":"Отличное начало. У нас хотя бы есть что-то общее?","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","italic":false},{"id":"3c3daf95-c5a8-519d-b1a8-20674abdf66c","text":"Он знает о магазине то, что не пишет в отчётах. Постарайся его разговорить.","characterId":"c15323c4-79bc-4b5d-868f-fff59ea61a0b","emotionId":"fdf2ff59-2e09-59fc-a1ba-d3f557781c3a","italic":false}],"route":{"next":"24c99146-e7e6-551a-99bf-29988046b92b","statId":"","operator":">=","value":0,"yes":"","no":""},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[]},{"id":"24c99146-e7e6-551a-99bf-29988046b92b","name":"Человек из прошлого","backgroundId":"ae067d37-2695-5239-9276-39224dc00643","characterId":"","emotionId":"","text":"В кабинете пахло бумагой и старым кофе. За столом сидел мужчина с усталым лицом.","italic":false,"lines":[{"id":"7bb75a34-f5ac-572b-9d81-31e52123886d","text":"Серафима?.. Нет. Этого не может быть.","characterId":"116ee990-c630-539f-a9fd-2af94347ab2f","emotionId":"cc5dd037-acbd-5751-95df-7fd590b49b42","italic":false},{"id":"20a878ae-a04d-508f-bf76-758ed2c8788b","text":"Сегодня меня зовут иначе. Мы здесь не для разговора о прошлом.","characterId":"c15323c4-79bc-4b5d-868f-fff59ea61a0b","emotionId":"fdf2ff59-2e09-59fc-a1ba-d3f557781c3a","italic":false},{"id":"22d3ddf3-f4c7-59c0-a245-5c828901d13c","text":"В прошлый раз ты тоже сказала, что всё под контролем. После этого я потерял работу.","characterId":"116ee990-c630-539f-a9fd-2af94347ab2f","emotionId":"cc5dd037-acbd-5751-95df-7fd590b49b42","italic":false},{"id":"4442bae4-1f76-5095-b52e-733df52e1c3b","text":"Вижу, знакомиться можно и без представления.","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","italic":false}],"route":{"next":"f89d71aa-89c4-55a9-a7f3-1ba94e2291a5","statId":"","operator":">=","value":0,"yes":"","no":""},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[]},{"id":"f89d71aa-89c4-55a9-a7f3-1ba94e2291a5","name":"Условия Виктора","backgroundId":"ae067d37-2695-5239-9276-39224dc00643","characterId":"116ee990-c630-539f-a9fd-2af94347ab2f","emotionId":"cc5dd037-acbd-5751-95df-7fd590b49b42","text":"Скоро региональное руководство будет пересматривать управление магазином. Есть человек, который подготовит заключение.","italic":false,"lines":[{"id":"c16731b7-c09d-5bca-8255-45f838cf4541","text":"И ты знаешь, кто именно.","characterId":"c15323c4-79bc-4b5d-868f-fff59ea61a0b","emotionId":"fdf2ff59-2e09-59fc-a1ba-d3f557781c3a","italic":false},{"id":"3fcd423d-e935-561e-be80-5769b032e9b4","text":"Знаю. Но прежде хочу понять, зачем вам это. И можно ли верить хотя бы одному человеку в этой комнате.","characterId":"116ee990-c630-539f-a9fd-2af94347ab2f","emotionId":"cc5dd037-acbd-5751-95df-7fd590b49b42","italic":false},{"id":"ff2b1c5e-d1a5-57a4-8ad7-69b5cd26d892","text":"Виктор посмотрел на Зою. С. С. ничего не сказала.","characterId":"","emotionId":"","italic":false}],"route":{"next":"","statId":"","operator":">=","value":0,"yes":"","no":""},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[{"id":"8ff77868-7f11-53b5-9ab7-d9715c09eb19","text":"Выслушать Виктора наедине","nextSceneId":"e62b2cf9-9fc8-5f1d-92b2-1fc8da5d25e5","money":0,"cost":0,"statId":"","statChange":0,"extraStatId":"","extraStatChange":0,"important":false,"fuelCost":0,"fuelGain":0,"condition":{"statId":"","operator":">=","value":0,"yes":"","no":""},"requirement":{"statId":"","operator":">=","value":0}},{"id":"3422e8a5-5684-5068-bbef-b580dbfeeaa1","text":"Поддержать С. С. и вернуться к делу","nextSceneId":"d07d700e-4527-5e46-a6a8-56498c63a507","money":0,"cost":0,"statId":"2f490ab7-a797-5d8a-bf2c-367d514dd1ad","statChange":-1,"extraStatId":"","extraStatChange":0,"important":false,"fuelCost":0,"fuelGain":0,"condition":{"statId":"","operator":">=","value":0,"yes":"","no":""},"requirement":{"statId":"","operator":">=","value":0}},{"id":"1394ce6d-0bbe-5e90-80a5-e48003b3d6fe","text":"Предложить разговор за чаем · 5 ✦","nextSceneId":"5b3b5f51-3413-5224-930b-0f2ceba3ebe1","money":0,"cost":5,"statId":"","statChange":0,"extraStatId":"","extraStatChange":0,"important":false,"fuelCost":0,"fuelGain":0,"condition":{"statId":"","operator":">=","value":0,"yes":"","no":""},"requirement":{"statId":"","operator":">=","value":0}}]},{"id":"e62b2cf9-9fc8-5f1d-92b2-1fc8da5d25e5","name":"Разговор без С. С.","backgroundId":"ae067d37-2695-5239-9276-39224dc00643","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","text":"Дайте нам несколько минут. Я хочу услышать его версию.","italic":false,"lines":[{"id":"bb18dbe4-249c-5fcd-8eeb-8550206224fe","text":"Когда-то я подписал бумаги, которых не понял. Потом остался крайним.","characterId":"116ee990-c630-539f-a9fd-2af94347ab2f","emotionId":"cc5dd037-acbd-5751-95df-7fd590b49b42","italic":false},{"id":"34bf320f-b42d-5f92-8205-9d8b747eca54","text":"Вы не обязаны рассказывать всё сразу. Но нам нужно знать, чего бояться.","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","italic":false},{"id":"24907e8e-c202-5227-afba-51f469275f0d","text":"Виктор внимательно посмотрел на неё и задумался.","characterId":"","emotionId":"","italic":false}],"route":{"next":"","statId":"f98cb989-552e-4ec1-bbb1-9e4839c49d0e","operator":">=","value":2,"yes":"662fd56a-d3fd-52aa-8508-ef602633cbc3","no":"1d7cc5bb-b276-5eb2-96ed-f1d5a5e690c8"},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[]},{"id":"662fd56a-d3fd-52aa-8508-ef602633cbc3","name":"Предупреждение Виктора","backgroundId":"ae067d37-2695-5239-9276-39224dc00643","characterId":"116ee990-c630-539f-a9fd-2af94347ab2f","emotionId":"cc5dd037-acbd-5751-95df-7fd590b49b42","text":"Человека из руководства зовут Павел Андреевич. Он будет смотреть и на показатели, и на жалобы сотрудников.","italic":false,"lines":[{"id":"10596d09-c107-526a-b139-a20e06710a2c","text":"А если С. С. скажет, что всё просчитала, спроси её про серую папку.","characterId":"116ee990-c630-539f-a9fd-2af94347ab2f","emotionId":"cc5dd037-acbd-5751-95df-7fd590b49b42","italic":false},{"id":"2e4d2042-3657-5643-895f-3294be79bea4","text":"Похоже, у всех вокруг меня есть цвет, который лучше не называть.","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","italic":false},{"id":"fa786a05-8a15-5ecb-b973-05d8cb9d5b29","text":"Виктор продиктовал номер и попросил не передавать его без разрешения.","characterId":"","emotionId":"","italic":false}],"route":{"next":"","statId":"","operator":">=","value":0,"yes":"","no":""},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[{"id":"5390ec06-3534-500d-ba6a-f0bf48e76951","text":"Запомнить предупреждение","nextSceneId":"8e1b95df-fb7c-5e7c-a05c-e3e3dae4a5a3","money":0,"cost":0,"statId":"969b9685-ad54-5b0e-82e2-c9adb1b085b6","statChange":1,"extraStatId":"2f490ab7-a797-5d8a-bf2c-367d514dd1ad","extraStatChange":1,"important":false,"fuelCost":0,"fuelGain":0,"condition":{"statId":"","operator":">=","value":0,"yes":"","no":""},"requirement":{"statId":"","operator":">=","value":0}}]},{"id":"1d7cc5bb-b276-5eb2-96ed-f1d5a5e690c8","name":"Осторожный ответ","backgroundId":"ae067d37-2695-5239-9276-39224dc00643","characterId":"116ee990-c630-539f-a9fd-2af94347ab2f","emotionId":"cc5dd037-acbd-5751-95df-7fd590b49b42","text":"Я не готов назвать имя. Но могу передать записку позже.","italic":false,"lines":[{"id":"d90da9a5-902c-5d5e-b09e-d9940a2bb93f","text":"Хорошо. Только не исчезайте, как остальные загадочные люди в моей жизни.","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","italic":false},{"id":"6faef8dd-a288-519c-bd12-58b831948a45","text":"Виктор впервые улыбнулся. Доверия пока было недостаточно для большего.","characterId":"","emotionId":"","italic":false}],"route":{"next":"8e1b95df-fb7c-5e7c-a05c-e3e3dae4a5a3","statId":"","operator":">=","value":0,"yes":"","no":""},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[]},{"id":"d07d700e-4527-5e46-a6a8-56498c63a507","name":"Коротко по делу","backgroundId":"ae067d37-2695-5239-9276-39224dc00643","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","text":"Вы можете спорить после того, как объясните, что происходит в магазине.","italic":false,"lines":[{"id":"ed01df21-4ae8-584a-82e0-b05abbead8a0","text":"Ладно. Руководство недовольно жалобами и готовит проверку.","characterId":"116ee990-c630-539f-a9fd-2af94347ab2f","emotionId":"cc5dd037-acbd-5751-95df-7fd590b49b42","italic":false},{"id":"c619eabe-a4bd-51ad-992b-e9dd5b7ef596","text":"Он протянул С. С. список, но на вопросы Зои отвечать больше не стал.","characterId":"","emotionId":"","italic":false},{"id":"27acf60f-0780-5872-8bee-0fe7998e8096","text":"Этого достаточно. Пока.","characterId":"c15323c4-79bc-4b5d-868f-fff59ea61a0b","emotionId":"fdf2ff59-2e09-59fc-a1ba-d3f557781c3a","italic":false}],"route":{"next":"8e1b95df-fb7c-5e7c-a05c-e3e3dae4a5a3","statId":"","operator":">=","value":0,"yes":"","no":""},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[]},{"id":"5b3b5f51-3413-5224-930b-0f2ceba3ebe1","name":"Разговор за чаем","backgroundId":"ae067d37-2695-5239-9276-39224dc00643","characterId":"","emotionId":"","text":"Зоя предложила спуститься за чаем. Пять звёздочек исчезли из кошелька, но разговор стал спокойнее.","italic":false,"lines":[{"id":"4076a8b6-f76f-5658-9bc2-eb7dd8ae2fae","text":"Руководству нужен человек, который наведёт порядок без новой волны увольнений.","characterId":"116ee990-c630-539f-a9fd-2af94347ab2f","emotionId":"cc5dd037-acbd-5751-95df-7fd590b49b42","italic":false},{"id":"8bd04ac5-5ac5-5410-b005-210b6fece252","text":"Уже звучит как работа сложнее моей предыдущей.","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","italic":false},{"id":"784447ad-2a1b-5580-a15f-2b7a1c390f23","text":"Виктор назвал имя проверяющего. Но о собственном прошлом говорить не захотел.","characterId":"","emotionId":"","italic":false}],"route":{"next":"8e1b95df-fb7c-5e7c-a05c-e3e3dae4a5a3","statId":"","operator":">=","value":0,"yes":"","no":""},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[]},{"id":"8e1b95df-fb7c-5e7c-a05c-e3e3dae4a5a3","name":"Неудобный вопрос","backgroundId":"ae067d37-2695-5239-9276-39224dc00643","characterId":"","emotionId":"","text":"У двери Зоя заметила на телефоне С. С. старое сообщение с пометкой «серое дело».","italic":false,"lines":[],"route":{"next":"","statId":"969b9685-ad54-5b0e-82e2-c9adb1b085b6","operator":">=","value":1,"yes":"ac7a986d-63ad-5e0d-9a29-a6976af18d1b","no":"79cbc21d-cdc0-563e-9d38-d89d4ba0fd75"},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[]},{"id":"ac7a986d-63ad-5e0d-9a29-a6976af18d1b","name":"Серая папка","backgroundId":"ae067d37-2695-5239-9276-39224dc00643","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","text":"Виктор сказал, что мне стоит спросить про серую папку.","italic":false,"lines":[{"id":"f847beac-c03c-571e-a798-bbf19afe4e0b","text":"Виктор слишком много разговаривает.","characterId":"c15323c4-79bc-4b5d-868f-fff59ea61a0b","emotionId":"fdf2ff59-2e09-59fc-a1ba-d3f557781c3a","italic":false},{"id":"57a7101a-7f6a-5acf-b8e5-1527a224ad76","text":"С. С. остановилась, ожидая, продолжит ли Зоя.","characterId":"","emotionId":"","italic":false}],"route":{"next":"","statId":"","operator":">=","value":0,"yes":"","no":""},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[{"id":"27db332f-fb04-5cb8-897b-23a2286819d5","text":"Спросить прямо","nextSceneId":"856a8d4a-72c7-5362-be28-37807ab17eea","money":0,"cost":0,"statId":"","statChange":0,"extraStatId":"","extraStatChange":0,"important":false,"fuelCost":0,"fuelGain":0,"condition":{"statId":"","operator":">=","value":0,"yes":"","no":""},"requirement":{"statId":"439a5762-6ae1-49cb-9f20-164fbb7584e2","operator":">=","value":2}},{"id":"b5a896b9-8543-5f00-97c0-094779a01753","text":"Запомнить и подождать","nextSceneId":"e25b7621-0bfa-57cd-b5b2-832c6648c65f","money":0,"cost":0,"statId":"","statChange":0,"extraStatId":"","extraStatChange":0,"important":false,"fuelCost":0,"fuelGain":0,"condition":{"statId":"","operator":">=","value":0,"yes":"","no":""},"requirement":{"statId":"","operator":">=","value":0}}]},{"id":"856a8d4a-72c7-5362-be28-37807ab17eea","name":"Обещание ответа","backgroundId":"ae067d37-2695-5239-9276-39224dc00643","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","text":"Он не обязан мне нравиться. Но я не собираюсь идти вслепую.","italic":false,"lines":[{"id":"31453787-2182-51cc-a23a-791a089f25e7","text":"Мы работали вместе. Что было в папке, я расскажу, когда буду уверена, что это не навредит делу.","characterId":"c15323c4-79bc-4b5d-868f-fff59ea61a0b","emotionId":"fdf2ff59-2e09-59fc-a1ba-d3f557781c3a","italic":false},{"id":"a4e7237b-6e28-56ae-9e95-e19531ed1770","text":"Я запомню это обещание.","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","italic":false},{"id":"347f738b-4d10-55bf-87cd-48c15317434c","text":"Ответа было мало, но С. С. впервые признала, что скрывает часть истории.","characterId":"","emotionId":"","italic":false}],"route":{"next":"79cbc21d-cdc0-563e-9d38-d89d4ba0fd75","statId":"","operator":">=","value":0,"yes":"","no":""},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[]},{"id":"e25b7621-0bfa-57cd-b5b2-832c6648c65f","name":"Отложенный вопрос","backgroundId":"ae067d37-2695-5239-9276-39224dc00643","characterId":"","emotionId":"","text":"Зоя решила пока не давить. Название папки она записала, чтобы вернуться к нему позже.","italic":false,"lines":[{"id":"bbfceb82-54f5-53e0-8430-1f51f67d279f","text":"Иногда лучше сначала узнать, какой вопрос задавать.","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","italic":false}],"route":{"next":"79cbc21d-cdc0-563e-9d38-d89d4ba0fd75","statId":"","operator":">=","value":0,"yes":"","no":""},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[]},{"id":"79cbc21d-cdc0-563e-9d38-d89d4ba0fd75","name":"Взгляд покупателя","backgroundId":"8db5f795-6bdf-5e42-82b1-095956df946e","characterId":"c15323c4-79bc-4b5d-868f-fff59ea61a0b","emotionId":"fdf2ff59-2e09-59fc-a1ba-d3f557781c3a","text":"Теперь зайди в магазин. Посмотри, что увидит обычный покупатель и будущий проверяющий.","italic":false,"lines":[{"id":"1ef91b50-fcb7-54d7-9f77-8736f1e5589d","text":"У кассы сотрудница узнала Зою.","characterId":"","emotionId":"","italic":false},{"id":"d298efeb-98cc-56d4-903b-63705cfcdf0d","text":"— Вы же с мясокомбината? Про вас говорили.","characterId":"","emotionId":"","italic":false},{"id":"bbd348c8-70b9-50d8-8382-4795385d4573","text":"Надеюсь, хотя бы без подробного списка колбасы.","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","italic":false}],"route":{"next":"","statId":"","operator":">=","value":0,"yes":"","no":""},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[{"id":"782c733a-ac60-52a0-b2d5-55a43543a307","text":"Открыто рассказать свою версию","nextSceneId":"1d968c5a-144d-599a-8f17-0b6e353e7e9e","money":0,"cost":0,"statId":"","statChange":0,"extraStatId":"","extraStatChange":0,"important":false,"fuelCost":0,"fuelGain":0,"condition":{"statId":"","operator":">=","value":0,"yes":"","no":""},"requirement":{"statId":"f98cb989-552e-4ec1-bbb1-9e4839c49d0e","operator":">=","value":2}},{"id":"437ead0c-a345-5bed-b875-cb026994fcd3","text":"Сказать, что пришла за покупками","nextSceneId":"1c4e67d9-ece6-5360-9c6b-9cf05aef20cc","money":0,"cost":0,"statId":"","statChange":0,"extraStatId":"","extraStatChange":0,"important":false,"fuelCost":0,"fuelGain":0,"condition":{"statId":"","operator":">=","value":0,"yes":"","no":""},"requirement":{"statId":"","operator":">=","value":0}},{"id":"65df61ec-6895-5675-9080-e1027d34449c","text":"Купить чай и задержаться у кассы · 3 ✦","nextSceneId":"1f074161-144f-5aa3-96b1-4f8c0e658c8f","money":0,"cost":3,"statId":"","statChange":0,"extraStatId":"","extraStatChange":0,"important":false,"fuelCost":0,"fuelGain":0,"condition":{"statId":"","operator":">=","value":0,"yes":"","no":""},"requirement":{"statId":"","operator":">=","value":0}}]},{"id":"1d968c5a-144d-599a-8f17-0b6e353e7e9e","name":"Разговор у кассы","backgroundId":"8db5f795-6bdf-5e42-82b1-095956df946e","characterId":"","emotionId":"","text":"Сотрудница засмеялась и призналась, что здесь люди тоже устали от постоянных новых указаний.","italic":false,"lines":[{"id":"f625fc24-acc5-5671-8c26-cec4c8aeca6b","text":"Значит, проблема не только в том, сколько человек стоит в очереди.","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","italic":false},{"id":"103e928e-0218-5599-a261-47fb04cafc0f","text":"Она запомнила слова сотрудницы и вышла к С. С.","characterId":"","emotionId":"","italic":false}],"route":{"next":"a2391d2b-90d0-58b0-a8a9-4b66907d2adb","statId":"","operator":">=","value":0,"yes":"","no":""},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[]},{"id":"1c4e67d9-ece6-5360-9c6b-9cf05aef20cc","name":"Тихое наблюдение","backgroundId":"8db5f795-6bdf-5e42-82b1-095956df946e","characterId":"","emotionId":"","text":"Зоя не стала привлекать внимание. Она заметила очередь и то, как часто сотрудники спрашивали друг друга об обязанностях.","italic":false,"lines":[{"id":"3bbb1351-0a6e-5c10-8685-9bb684b57815","text":"Снаружи всё выглядит проще, чем внутри. Это я уже где-то слышала.","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","italic":false}],"route":{"next":"a2391d2b-90d0-58b0-a8a9-4b66907d2adb","statId":"","operator":">=","value":0,"yes":"","no":""},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[]},{"id":"1f074161-144f-5aa3-96b1-4f8c0e658c8f","name":"Чай и разговор","backgroundId":"8db5f795-6bdf-5e42-82b1-095956df946e","characterId":"","emotionId":"","text":"Пока кассир пробивала чай, Зоя услышала разговор о предстоящей проверке.","italic":false,"lines":[{"id":"54653152-cb43-58f2-a457-41a09c4e05fd","text":"Сотрудницы не знали точного времени и спорили, кто должен готовить документы.","characterId":"","emotionId":"","italic":false},{"id":"372e6889-97df-5b17-9ce5-aaf5bd822321","text":"За три звёздочки — чай и повод задуматься. Неплохо.","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","italic":false}],"route":{"next":"a2391d2b-90d0-58b0-a8a9-4b66907d2adb","statId":"","operator":">=","value":0,"yes":"","no":""},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[]},{"id":"a2391d2b-90d0-58b0-a8a9-4b66907d2adb","name":"Выводы для С. С.","backgroundId":"08eee936-c9e9-4abc-b768-70914bb2b1fe","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","text":"В магазине люди не всегда понимают, кто за что отвечает. А покупатели видят только очередь.","italic":false,"lines":[{"id":"6fd81c48-c83d-57e3-9f13-36a542f7b9dc","text":"Руководство услышит о порядке. Но твои слова помогут объяснить, зачем он нужен.","characterId":"c15323c4-79bc-4b5d-868f-fff59ea61a0b","emotionId":"fdf2ff59-2e09-59fc-a1ba-d3f557781c3a","italic":false},{"id":"683c8507-752e-57f0-a458-144b90990673","text":"С. С. записала наблюдения и быстро закрыла папку.","characterId":"","emotionId":"","italic":false},{"id":"0ebecebd-a208-5af6-83aa-e228c30a0711","text":"Последний лист тоже про очереди?","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","italic":false},{"id":"8625b8ac-7019-5a4d-ad5e-aad97ef1752c","text":"Сегодня — не про них. Едем к Наталье.","characterId":"c15323c4-79bc-4b5d-868f-fff59ea61a0b","emotionId":"fdf2ff59-2e09-59fc-a1ba-d3f557781c3a","italic":false}],"route":{"next":"5c55fef6-a706-5fe6-8c35-1f3496c6dcdc","statId":"","operator":">=","value":0,"yes":"","no":""},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[]},{"id":"b2053e4d-79fe-515e-a0d6-28f215244461","name":"У служебного входа","backgroundId":"e480419c-c994-5e05-ac55-e4691c06eb6c","characterId":"","emotionId":"","text":"Зоя пришла к служебной двери магазина.","italic":false,"lines":[],"route":{"next":"","statId":"0c14bd21-7b6e-5d6c-9ffc-ef28f92c1783","operator":">=","value":1,"yes":"3ba01332-2c39-5875-8425-7a0293ac27b4","no":"3a00520b-778a-5366-9b29-3f2d38a2d2a6"},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[]},{"id":"3ba01332-2c39-5875-8425-7a0293ac27b4","name":"Встреча вовремя","backgroundId":"e480419c-c994-5e05-ac55-e4691c06eb6c","characterId":"","emotionId":"","text":"Из-за двери слышны первые слова спора двух сотрудниц. Наталья только собирается войти.","italic":false,"lines":[{"id":"33b621eb-54b9-526b-9bf8-25202a484d49","text":"Успела к самому началу?","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","italic":false}],"route":{"next":"a9d0b9af-d701-5490-85fd-92d76c91a8c2","statId":"","operator":">=","value":0,"yes":"","no":""},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[]},{"id":"3a00520b-778a-5366-9b29-3f2d38a2d2a6","name":"Встреча с опозданием","backgroundId":"e480419c-c994-5e05-ac55-e4691c06eb6c","characterId":"92f40577-c7d5-4e6e-97c6-6081558bb263","emotionId":"f7ce1053-2001-4b91-980e-80208645e976","text":"У нас уже начался спор. И у тебя пять минут, чтобы его не усугубить.","italic":false,"lines":[{"id":"7930185b-e863-519f-b751-c468a5c98076","text":"Звучит как работа моей мечты.","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","italic":false}],"route":{"next":"a9d0b9af-d701-5490-85fd-92d76c91a8c2","statId":"","operator":">=","value":0,"yes":"","no":""},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[]},{"id":"a9d0b9af-d701-5490-85fd-92d76c91a8c2","name":"Служебный вход","backgroundId":"e480419c-c994-5e05-ac55-e4691c06eb6c","characterId":"92f40577-c7d5-4e6e-97c6-6081558bb263","emotionId":"f7ce1053-2001-4b91-980e-80208645e976","text":"Сегодня увидишь магазин с другой стороны. Только не говори людям, что пришла изучать коллектив.","italic":false,"lines":[{"id":"1e8e7889-60aa-58e2-83ce-b64c13046e02","text":"А если скажу, что пришла работать?","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","italic":false},{"id":"1645977e-f2c3-5d38-99f2-dd94aea8aef4","text":"Тогда тебя вполне могут попросить работать.","characterId":"92f40577-c7d5-4e6e-97c6-6081558bb263","emotionId":"f7ce1053-2001-4b91-980e-80208645e976","italic":false},{"id":"cd421a06-d095-5051-b2e1-5a65bb64798f","text":"Наталья открыла служебную дверь и провела Зою в комнату сотрудников.","characterId":"","emotionId":"","italic":false}],"route":{"next":"44b15c39-c1c0-5db4-a69d-0f0b1aacaf25","statId":"","operator":">=","value":0,"yes":"","no":""},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[]},{"id":"44b15c39-c1c0-5db4-a69d-0f0b1aacaf25","name":"Ирина и Лена","backgroundId":"df9c6ddc-8a41-57c8-8c1e-fc9dba210967","characterId":"8dba2649-c728-5c4d-8dfb-bd4b7f5cf15d","emotionId":"a9c4fb91-6c18-5587-a4df-97749af68e25","text":"Вчера я осталась после смены, потому что Лена не закончила работу.","italic":false,"lines":[{"id":"f01778d7-0519-5d81-830f-d1a1ec5b10c9","text":"Мне никто не сказал, что это тоже моя работа! Я спрашивала.","characterId":"c6d58640-e697-575d-8b45-15f1825b2ec5","emotionId":"aed1409b-0d32-56a4-8c32-45fef12e67a2","italic":false},{"id":"1e0b3f31-ae28-5f37-83ae-90eae960540a","text":"А у меня была очередь и телефон звонил без остановки.","characterId":"8dba2649-c728-5c4d-8dfb-bd4b7f5cf15d","emotionId":"a9c4fb91-6c18-5587-a4df-97749af68e25","italic":false},{"id":"8d1aad8e-3179-5dbc-b44b-1729ab1270e4","text":"Наталья не вмешивалась. Она ждала, как Зоя поведёт себя с людьми, которым не может ничего приказать.","characterId":"","emotionId":"","italic":false}],"route":{"next":"","statId":"","operator":">=","value":0,"yes":"","no":""},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[{"id":"de0d8330-791f-5098-a271-b5c74a367799","text":"Выслушать обеих по отдельности","nextSceneId":"d989c850-6e2b-5054-a52a-9cc98aaf3e4d","money":0,"cost":0,"statId":"4438bdae-d2e4-5793-87fe-31241baa5d17","statChange":1,"extraStatId":"2e05fe73-9c08-5c4d-a109-8bf59c6bc049","extraStatChange":1,"important":false,"fuelCost":0,"fuelGain":0,"condition":{"statId":"","operator":">=","value":0,"yes":"","no":""},"requirement":{"statId":"","operator":">=","value":0}},{"id":"b311e870-b4d7-5132-87ff-ae3a269a996f","text":"Поддержать Ирину","nextSceneId":"e5e0a03f-3639-531d-b91c-50e216052d4f","money":0,"cost":0,"statId":"4438bdae-d2e4-5793-87fe-31241baa5d17","statChange":2,"extraStatId":"2e05fe73-9c08-5c4d-a109-8bf59c6bc049","extraStatChange":-1,"important":false,"fuelCost":0,"fuelGain":0,"condition":{"statId":"","operator":">=","value":0,"yes":"","no":""},"requirement":{"statId":"","operator":">=","value":0}},{"id":"250413e5-cdd5-5da8-85a3-1ac8ecb93157","text":"Заступиться за Лену","nextSceneId":"8d643fa3-575d-53f6-906e-36877aa5b432","money":0,"cost":0,"statId":"2e05fe73-9c08-5c4d-a109-8bf59c6bc049","statChange":2,"extraStatId":"4438bdae-d2e4-5793-87fe-31241baa5d17","extraStatChange":-1,"important":false,"fuelCost":0,"fuelGain":0,"condition":{"statId":"","operator":">=","value":0,"yes":"","no":""},"requirement":{"statId":"","operator":">=","value":0}},{"id":"5e719cbb-90f1-5307-8d1f-82121ff1014f","text":"Купить чай и предложить перерыв · 3 ✦","nextSceneId":"06072ac0-2800-5d29-95f2-a6e998578b4c","money":0,"cost":3,"statId":"","statChange":0,"extraStatId":"","extraStatChange":0,"important":false,"fuelCost":0,"fuelGain":0,"condition":{"statId":"","operator":">=","value":0,"yes":"","no":""},"requirement":{"statId":"","operator":">=","value":0}}]},{"id":"d989c850-6e2b-5054-a52a-9cc98aaf3e4d","name":"Два разговора","backgroundId":"df9c6ddc-8a41-57c8-8c1e-fc9dba210967","characterId":"c6d58640-e697-575d-8b45-15f1825b2ec5","emotionId":"aed1409b-0d32-56a4-8c32-45fef12e67a2","text":"Я не боюсь работы. Я боюсь снова спросить что-то глупое при всех.","italic":false,"lines":[{"id":"ac9c1bd7-e2ca-5e44-9fe5-14472b3d35b8","text":"Раньше я любила учить новичков. Теперь у меня просто нет на это времени.","characterId":"8dba2649-c728-5c4d-8dfb-bd4b7f5cf15d","emotionId":"a9c4fb91-6c18-5587-a4df-97749af68e25","italic":false},{"id":"83606fb8-2216-56d6-a442-58ba995ee0cd","text":"Значит, дело не в том, что одна не хочет помогать, а другая — работать.","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","italic":false},{"id":"d3aaab6d-98a6-55f8-b0a5-4f80f7c327e4","text":"Обе согласились попробовать записать обязанности и попросить время на обучение.","characterId":"","emotionId":"","italic":false}],"route":{"next":"bdbfdc9b-b38c-5a09-95ed-79dbe5201996","statId":"","operator":">=","value":0,"yes":"","no":""},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[]},{"id":"e5e0a03f-3639-531d-b91c-50e216052d4f","name":"Сторона Ирины","backgroundId":"df9c6ddc-8a41-57c8-8c1e-fc9dba210967","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","text":"Опыт нужно уважать. Нельзя ожидать, что за тебя постоянно всё сделают.","italic":false,"lines":[{"id":"4df86bf6-8499-58d4-ba46-1cafc3872ce2","text":"Спасибо. Я не отказываюсь помогать, но не могу работать за двоих.","characterId":"8dba2649-c728-5c4d-8dfb-bd4b7f5cf15d","emotionId":"a9c4fb91-6c18-5587-a4df-97749af68e25","italic":false},{"id":"082f35d4-2fd7-505a-9d74-2cfcd71051af","text":"Лена ничего не ответила. Позже Зоя услышала, как она сказала по телефону: «Она даже не разобралась».","characterId":"","emotionId":"","italic":false},{"id":"9a6d87b1-217c-5256-a27d-ad6457930d44","text":"Кажется, поддержать одну было проще, чем понять обеих.","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","italic":false}],"route":{"next":"bdbfdc9b-b38c-5a09-95ed-79dbe5201996","statId":"","operator":">=","value":0,"yes":"","no":""},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[]},{"id":"8d643fa3-575d-53f6-906e-36877aa5b432","name":"Сторона Лены","backgroundId":"df9c6ddc-8a41-57c8-8c1e-fc9dba210967","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","text":"Нельзя требовать от человека того, чему его никто не научил.","italic":false,"lines":[{"id":"0e36361c-1418-537d-a729-2fec4daf0fa1","text":"Я записала вопросы, но не знала, кому их задать.","characterId":"c6d58640-e697-575d-8b45-15f1825b2ec5","emotionId":"aed1409b-0d32-56a4-8c32-45fef12e67a2","italic":false},{"id":"3ac07b48-dfef-59fe-a687-e12d517fd466","text":"Ирина замолчала и вышла. Лена показала Зое расписание и отметила несколько непонятных смен.","characterId":"","emotionId":"","italic":false},{"id":"02b255b9-ce2a-5738-8fd3-4dea6f6e602d","text":"Теперь осталось поговорить с Ириной, когда она будет готова.","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","italic":false}],"route":{"next":"bdbfdc9b-b38c-5a09-95ed-79dbe5201996","statId":"","operator":">=","value":0,"yes":"","no":""},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[]},{"id":"06072ac0-2800-5d29-95f2-a6e998578b4c","name":"Небольшой перерыв","backgroundId":"df9c6ddc-8a41-57c8-8c1e-fc9dba210967","characterId":"","emotionId":"","text":"Зоя купила чай. Сам по себе он никого не помирил, но обе согласились присесть на пять минут.","italic":false,"lines":[{"id":"136b7c73-57a5-51c5-8ffb-eebae519f836","text":"Я не обещаю волшебное решение. Давайте хотя бы попробуем не перебивать друг друга.","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","italic":false}],"route":{"next":"","statId":"f98cb989-552e-4ec1-bbb1-9e4839c49d0e","operator":">=","value":2,"yes":"e19a7b36-1b30-5e4f-a6bb-5470bfcf47ad","no":"88dfcd71-c8e3-56d5-b514-e81ea0af7b24"},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[]},{"id":"e19a7b36-1b30-5e4f-a6bb-5470bfcf47ad","name":"Разговор за чаем","backgroundId":"df9c6ddc-8a41-57c8-8c1e-fc9dba210967","characterId":"8dba2649-c728-5c4d-8dfb-bd4b7f5cf15d","emotionId":"a9c4fb91-6c18-5587-a4df-97749af68e25","text":"Мне нужна помощь, а не ещё один повод задержаться.","italic":false,"lines":[{"id":"69a274ef-c557-5350-b72a-23f5dbbc6063","text":"А мне — человек, у которого можно спросить без страха.","characterId":"c6d58640-e697-575d-8b45-15f1825b2ec5","emotionId":"aed1409b-0d32-56a4-8c32-45fef12e67a2","italic":false},{"id":"dbe02541-6275-514c-bd67-c27fb6db8f78","text":"Значит, попросим Наталью выделить время на обучение и записать обязанности.","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","italic":false},{"id":"a60f1678-f9f3-5b8b-bfef-cc5870b2f7cc","text":"Обе согласились попробовать. На этот раз без взаимных обвинений.","characterId":"","emotionId":"","italic":false}],"route":{"next":"","statId":"","operator":">=","value":0,"yes":"","no":""},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[{"id":"2ff8401a-899c-5539-8dee-ef86df5ee4f0","text":"Поблагодарить обеих","nextSceneId":"bdbfdc9b-b38c-5a09-95ed-79dbe5201996","money":0,"cost":0,"statId":"4438bdae-d2e4-5793-87fe-31241baa5d17","statChange":1,"extraStatId":"2e05fe73-9c08-5c4d-a109-8bf59c6bc049","extraStatChange":1,"important":false,"fuelCost":0,"fuelGain":0,"condition":{"statId":"","operator":">=","value":0,"yes":"","no":""},"requirement":{"statId":"","operator":">=","value":0}}]},{"id":"88dfcd71-c8e3-56d5-b514-e81ea0af7b24","name":"Кого выслушать первым","backgroundId":"df9c6ddc-8a41-57c8-8c1e-fc9dba210967","characterId":"","emotionId":"","text":"Несмотря на чай, разговор снова стал напряжённым. Зое пришлось решить, с кого начать.","italic":false,"lines":[],"route":{"next":"","statId":"","operator":">=","value":0,"yes":"","no":""},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[{"id":"ae1515eb-c2e3-56c1-9d5f-eff0b9960144","text":"Сначала поговорить с Ириной","nextSceneId":"e5e0a03f-3639-531d-b91c-50e216052d4f","money":0,"cost":0,"statId":"4438bdae-d2e4-5793-87fe-31241baa5d17","statChange":1,"extraStatId":"","extraStatChange":0,"important":false,"fuelCost":0,"fuelGain":0,"condition":{"statId":"","operator":">=","value":0,"yes":"","no":""},"requirement":{"statId":"","operator":">=","value":0}},{"id":"d5202142-d15b-5660-9e15-94fc45216180","text":"Сначала поговорить с Леной","nextSceneId":"8d643fa3-575d-53f6-906e-36877aa5b432","money":0,"cost":0,"statId":"2e05fe73-9c08-5c4d-a109-8bf59c6bc049","statChange":1,"extraStatId":"","extraStatChange":0,"important":false,"fuelCost":0,"fuelGain":0,"condition":{"statId":"","operator":">=","value":0,"yes":"","no":""},"requirement":{"statId":"","operator":">=","value":0}}]},{"id":"bdbfdc9b-b38c-5a09-95ed-79dbe5201996","name":"Три наблюдения","backgroundId":"8db5f795-6bdf-5e42-82b1-095956df946e","characterId":"92f40577-c7d5-4e6e-97c6-6081558bb263","emotionId":"f7ce1053-2001-4b91-980e-80208645e976","text":"Попробуй записать три вещи, которые новый заведующий должен понять о магазине.","italic":false,"lines":[{"id":"e0572a4f-0d2a-5ea9-9cac-a1c983cb78b1","text":"Зоя прошла между рядами и обратила внимание на работу сотрудников и покупателей.","characterId":"","emotionId":"","italic":false},{"id":"d73b02a7-6c1d-55fc-956e-a25ddba71b28","text":"Обязанности непонятны. О переменах узнают слишком поздно. А покупатели видят только очередь.","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","italic":false},{"id":"273d6acd-1e54-5324-b99e-39387ca1a9d1","text":"Если я стану заведующей, попрошу людей рассказать это без страха наказания.","characterId":"92f40577-c7d5-4e6e-97c6-6081558bb263","emotionId":"f7ce1053-2001-4b91-980e-80208645e976","italic":false},{"id":"2499d92d-9bd3-59de-b949-d007cd4f4ae8","text":"Красиво звучит. Главное — не забыть, когда получишь кресло.","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","italic":false}],"route":{"next":"8af46d55-2cfd-5f64-98f8-e50ed8dd7036","statId":"","operator":">=","value":0,"yes":"","no":""},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[]},{"id":"8af46d55-2cfd-5f64-98f8-e50ed8dd7036","name":"Звонок С. С.","backgroundId":"df9c6ddc-8a41-57c8-8c1e-fc9dba210967","characterId":"","emotionId":"","text":"Телефон Натальи зазвонил. С. С. попросила привести Зою на общую встречу.","italic":false,"lines":[{"id":"72f09051-2b29-51cf-a782-0c595cf5ec26","text":"Она любит приходить с готовым ответом. Посмотрим, готова ли она услышать чужой.","characterId":"92f40577-c7d5-4e6e-97c6-6081558bb263","emotionId":"f7ce1053-2001-4b91-980e-80208645e976","italic":false},{"id":"4b2acac2-a23a-52a5-8045-3b780e8e38d4","text":"Перед уходом сотрудницы передали Зое записку с предложением для будущего заведующего.","characterId":"","emotionId":"","italic":false},{"id":"780fa402-168f-5e4b-b378-521880cb1008","text":"У меня теперь важный документ. Надеюсь, он переживёт поездку в сумке.","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","italic":false}],"route":{"next":"6211b7cf-eb95-56db-a6d8-30924fb2985e","statId":"","operator":">=","value":0,"yes":"","no":""},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[]},{"id":"5c55fef6-a706-5fe6-8c35-1f3496c6dcdc","name":"Оплата С. С.","backgroundId":"e2fb766b-c8a2-525b-8404-50c91eb3ed1e","characterId":"","emotionId":"","text":"На деревянной доске по-прежнему висела фотография «Санты» под надписью «Большой куш».","italic":false,"lines":[{"id":"5de0631b-8a7a-53c1-ac8d-b3d74d154151","text":"Мы выяснили, кто готовит заключение для руководства. Это твоя оплата за работу.","characterId":"c15323c4-79bc-4b5d-868f-fff59ea61a0b","emotionId":"fdf2ff59-2e09-59fc-a1ba-d3f557781c3a","italic":false},{"id":"5a117c3e-273d-5aec-8c76-0b072cce8af1","text":"Подождите. Это всё мне?","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","italic":false},{"id":"1f705f76-6434-51ad-b867-5e42a56b02c2","text":"Ты же не думала, что большой куш начинается с просьбы поработать бесплатно?","characterId":"c15323c4-79bc-4b5d-868f-fff59ea61a0b","emotionId":"fdf2ff59-2e09-59fc-a1ba-d3f557781c3a","italic":false}],"route":{"next":"","statId":"","operator":">=","value":0,"yes":"","no":""},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[{"id":"4bc3c126-82b3-5009-b765-bfc14c5fb7cd","text":"Получить оплату · +55 ✦","nextSceneId":"a5915eab-909d-516a-9098-8061c644f76f","money":55,"cost":0,"statId":"","statChange":0,"extraStatId":"","extraStatChange":0,"important":false,"fuelCost":0,"fuelGain":0,"condition":{"statId":"","operator":">=","value":0,"yes":"","no":""},"requirement":{"statId":"","operator":">=","value":0}}]},{"id":"6211b7cf-eb95-56db-a6d8-30924fb2985e","name":"Оплата Натальи","backgroundId":"e2fb766b-c8a2-525b-8404-50c91eb3ed1e","characterId":"","emotionId":"","text":"В комнате с деревянной доской С. С. уже ждала их. Наталья положила рядом записи Зои.","italic":false,"lines":[{"id":"03e3a612-7c69-582e-b092-1f846b56c30f","text":"Это предложения людей, которые работают в магазине каждый день. А это — твоя оплата.","characterId":"92f40577-c7d5-4e6e-97c6-6081558bb263","emotionId":"f7ce1053-2001-4b91-980e-80208645e976","italic":false},{"id":"a807a50d-73ee-555a-b386-80a2d281fb22","text":"Сорок пять? За один день?","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","italic":false},{"id":"f4761824-584b-5b5b-98ba-25747d32f854","text":"За работу. Ты заслужила это до того, как мы получили результат.","characterId":"92f40577-c7d5-4e6e-97c6-6081558bb263","emotionId":"f7ce1053-2001-4b91-980e-80208645e976","italic":false}],"route":{"next":"","statId":"","operator":">=","value":0,"yes":"","no":""},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[{"id":"362697eb-4b55-5c20-9399-d101717c4f21","text":"Получить оплату · +45 ✦","nextSceneId":"a5915eab-909d-516a-9098-8061c644f76f","money":45,"cost":0,"statId":"","statChange":0,"extraStatId":"","extraStatChange":0,"important":false,"fuelCost":0,"fuelGain":0,"condition":{"statId":"","operator":">=","value":0,"yes":"","no":""},"requirement":{"statId":"","operator":">=","value":0}}]},{"id":"a5915eab-909d-516a-9098-8061c644f76f","name":"Вспомнить о долге","backgroundId":"e2fb766b-c8a2-525b-8404-50c91eb3ed1e","characterId":"","emotionId":"","text":"Деньги напомнили Зое о подруге, которая выручила её после ссоры с мужем.","italic":false,"lines":[],"route":{"next":"","statId":"9497ac4b-df8a-5778-aae1-64e6f79bfc50","operator":">","value":0,"yes":"b04c0e69-8f1f-54fc-bd46-cb6d961d8ce5","no":"bb897aba-da3c-559b-a80c-a4ed6718ce91"},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[]},{"id":"b04c0e69-8f1f-54fc-bd46-cb6d961d8ce5","name":"Позвонить подруге","backgroundId":"e2fb766b-c8a2-525b-8404-50c91eb3ed1e","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","text":"Я обещала вернуть деньги, когда смогу. Похоже, теперь могу.","italic":false,"lines":[{"id":"49260958-cf1e-5c31-a53f-23dc54bad7fc","text":"На телефоне было непрочитанное сообщение подруги: «Как ты там?»","characterId":"","emotionId":"","italic":false}],"route":{"next":"","statId":"","operator":">=","value":0,"yes":"","no":""},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[{"id":"47cc5512-7fe7-52fe-819e-c58bedc76911","text":"Вернуть весь долг · 20 ✦","nextSceneId":"eb4e1fc6-6994-5da8-9199-e5f2fb7248b9","money":0,"cost":20,"statId":"9497ac4b-df8a-5778-aae1-64e6f79bfc50","statChange":-20,"extraStatId":"","extraStatChange":0,"important":false,"fuelCost":0,"fuelGain":0,"condition":{"statId":"","operator":">=","value":0,"yes":"","no":""},"requirement":{"statId":"9497ac4b-df8a-5778-aae1-64e6f79bfc50","operator":">=","value":20}},{"id":"54ab7f06-2059-536f-bbe2-3d243d3ac8ef","text":"Вернуть половину · 10 ✦","nextSceneId":"e8da3085-8b31-5244-81fc-c2c20842fdd1","money":0,"cost":10,"statId":"9497ac4b-df8a-5778-aae1-64e6f79bfc50","statChange":-10,"extraStatId":"","extraStatChange":0,"important":false,"fuelCost":0,"fuelGain":0,"condition":{"statId":"","operator":">=","value":0,"yes":"","no":""},"requirement":{"statId":"9497ac4b-df8a-5778-aae1-64e6f79bfc50","operator":">=","value":10}},{"id":"50fa9f39-8f19-5c17-bea7-35ceb1629f7c","text":"Пока оставить деньги себе","nextSceneId":"84c38abd-2ef9-5760-a621-415c06989592","money":0,"cost":0,"statId":"","statChange":0,"extraStatId":"","extraStatChange":0,"important":false,"fuelCost":0,"fuelGain":0,"condition":{"statId":"","operator":">=","value":0,"yes":"","no":""},"requirement":{"statId":"","operator":">=","value":0}}]},{"id":"eb4e1fc6-6994-5da8-9199-e5f2fb7248b9","name":"Долг возвращён","backgroundId":"e2fb766b-c8a2-525b-8404-50c91eb3ed1e","characterId":"","emotionId":"","text":"Зоя перевела подруге двадцать звёздочек.","italic":false,"lines":[{"id":"631e47aa-1dad-5cbd-be3b-206832991f2b","text":"— Не ожидала так быстро. Главное, что ты в порядке.","characterId":"","emotionId":"","italic":false},{"id":"18c80e6d-6311-52ad-a05f-89059d4bae38","text":"Насчёт порядка пока не обещаю. Но долг я вернула.","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","italic":false},{"id":"a54c5f4d-f26c-5397-a84f-617f968a673e","text":"Подруга засмеялась и пообещала позвонить вечером.","characterId":"","emotionId":"","italic":false}],"route":{"next":"bb897aba-da3c-559b-a80c-a4ed6718ce91","statId":"","operator":">=","value":0,"yes":"","no":""},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[]},{"id":"e8da3085-8b31-5244-81fc-c2c20842fdd1","name":"Часть долга","backgroundId":"e2fb766b-c8a2-525b-8404-50c91eb3ed1e","characterId":"","emotionId":"","text":"Зоя перевела десять звёздочек и написала, что вернёт остальное позже.","italic":false,"lines":[{"id":"840f0691-1649-5a77-b5e1-c4c4ec1ae45b","text":"— Спасибо. И да, я помню, сколько осталось.","characterId":"","emotionId":"","italic":false},{"id":"88ffe011-ab80-50da-a8d4-6b600cbce255","text":"Вот поэтому я и не стала делать вид, что забыла.","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","italic":false}],"route":{"next":"bb897aba-da3c-559b-a80c-a4ed6718ce91","statId":"","operator":">=","value":0,"yes":"","no":""},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[]},{"id":"84c38abd-2ef9-5760-a621-415c06989592","name":"Долг остаётся","backgroundId":"e2fb766b-c8a2-525b-8404-50c91eb3ed1e","characterId":"","emotionId":"","text":"Зоя решила оставить деньги на подготовку. Сообщение подруги осталось непрочитанным.","italic":false,"lines":[{"id":"1abc4eaa-e5ee-5596-b55d-dafd39eabb1c","text":"Я верну. Только сначала нужно понять, сколько нам понадобится дальше.","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","italic":false},{"id":"28217f0e-2b5e-5502-9685-2c12183303e6","text":"Долг не исчез, а разговор с подругой лишь откладывался.","characterId":"","emotionId":"","italic":false}],"route":{"next":"bb897aba-da3c-559b-a80c-a4ed6718ce91","statId":"","operator":">=","value":0,"yes":"","no":""},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[]},{"id":"bb897aba-da3c-559b-a80c-a4ed6718ce91","name":"Кто займёт кресло","backgroundId":"e2fb766b-c8a2-525b-8404-50c91eb3ed1e","characterId":"92f40577-c7d5-4e6e-97c6-6081558bb263","emotionId":"f7ce1053-2001-4b91-980e-80208645e976","text":"Пора решить, чьё имя будет на карточке «Заведующий».","italic":false,"lines":[{"id":"43e684f1-620e-553e-884f-c0318589184a","text":"Моё.","characterId":"c15323c4-79bc-4b5d-868f-fff59ea61a0b","emotionId":"fdf2ff59-2e09-59fc-a1ba-d3f557781c3a","italic":false},{"id":"55ae06f2-c45c-5c64-9dc0-d2c6248ee5af","text":"Я знаю магазин и разговаривала с людьми. Ты умеешь давить на руководство, но это не то же самое, что управлять командой.","characterId":"92f40577-c7d5-4e6e-97c6-6081558bb263","emotionId":"f7ce1053-2001-4b91-980e-80208645e976","italic":false},{"id":"e62b376f-d42d-5a28-a659-fca9fd6f5cf3","text":"А без поддержки руководства ты не получишь эту должность ни на один день.","characterId":"c15323c4-79bc-4b5d-868f-fff59ea61a0b","emotionId":"fdf2ff59-2e09-59fc-a1ba-d3f557781c3a","italic":false},{"id":"f634d902-7b2f-585c-b589-1173bf55476d","text":"Может, сначала выясним, что входит в обязанности заведующего?","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","italic":false},{"id":"23a5d433-2e2f-54e4-9711-5a0fd5d05081","text":"Обе одновременно повернулись к ней: «Мы знаем».","characterId":"","emotionId":"","italic":false},{"id":"fcf062ce-7fa8-51b4-8398-0a1e721f7a27","text":"Вижу. Просто проверяла.","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","italic":false}],"route":{"next":"","statId":"","operator":">=","value":0,"yes":"","no":""},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[{"id":"0fbbc3b4-114f-5771-a906-577a3097b195","text":"Поддержать С. С. · ей проще договориться с руководством","nextSceneId":"9781a7c6-b027-5b01-96eb-49506ea3a0c6","money":0,"cost":0,"statId":"3262e185-5ef8-518d-9dda-b07fd3c4f3be","statChange":1,"extraStatId":"","extraStatChange":0,"important":true,"fuelCost":0,"fuelGain":0,"condition":{"statId":"","operator":">=","value":0,"yes":"","no":""},"requirement":{"statId":"","operator":">=","value":0}},{"id":"3b648081-59d4-5b15-81c6-8f779a691a0b","text":"Поддержать Наталью · она ближе к сотрудникам","nextSceneId":"236990c4-a32a-5227-811b-e63af36faec5","money":0,"cost":0,"statId":"3262e185-5ef8-518d-9dda-b07fd3c4f3be","statChange":-1,"extraStatId":"","extraStatChange":0,"important":true,"fuelCost":0,"fuelGain":0,"condition":{"statId":"","operator":">=","value":0,"yes":"","no":""},"requirement":{"statId":"","operator":">=","value":0}},{"id":"ee099264-0c44-58ce-8638-9bd4b8b9c73f","text":"Не выбирать сторону · сначала нужен общий план","nextSceneId":"ab8a862d-b0f7-55dc-881f-7855e69e17af","money":0,"cost":0,"statId":"","statChange":0,"extraStatId":"","extraStatChange":0,"important":true,"fuelCost":0,"fuelGain":0,"condition":{"statId":"","operator":">=","value":0,"yes":"","no":""},"requirement":{"statId":"439a5762-6ae1-49cb-9f20-164fbb7584e2","operator":">=","value":2}}]},{"id":"9781a7c6-b027-5b01-96eb-49506ea3a0c6","name":"Поддержать С. С.","backgroundId":"e2fb766b-c8a2-525b-8404-50c91eb3ed1e","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","text":"Сейчас нужен человек, который сможет договориться с руководством. Это С. С.","italic":false,"lines":[{"id":"6e4410fd-a3a0-5067-8dd5-e19c0134fba4","text":"Наконец-то кто-то смотрит дальше завтрашнего дня.","characterId":"c15323c4-79bc-4b5d-868f-fff59ea61a0b","emotionId":"fdf2ff59-2e09-59fc-a1ba-d3f557781c3a","italic":false},{"id":"eb12a0e4-a91b-573e-8b25-ab292d23980f","text":"А потом не забудьте спросить сотрудников, захотят ли они с ней работать.","characterId":"92f40577-c7d5-4e6e-97c6-6081558bb263","emotionId":"f7ce1053-2001-4b91-980e-80208645e976","italic":false},{"id":"c5ec2d1a-4dc1-59af-a986-6bceb0cf5c0c","text":"Зоя понимала: её поддержка не закончила спор, а определила, с кем ей придётся отвечать за решение.","characterId":"","emotionId":"","italic":false}],"route":{"next":"498813db-8e8a-5dc6-a2c1-498a3a0b62f1","statId":"","operator":">=","value":0,"yes":"","no":""},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[]},{"id":"236990c4-a32a-5227-811b-e63af36faec5","name":"Поддержать Наталью","backgroundId":"e2fb766b-c8a2-525b-8404-50c91eb3ed1e","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","text":"Заведующий должен понимать, что происходит в магазине каждый день. Наталья ближе к людям.","italic":false,"lines":[{"id":"880b1a1b-f8cb-59ec-a9b0-957a50a8e91b","text":"Спасибо. Я не собираюсь делать вид, будто у меня уже есть все ответы.","characterId":"92f40577-c7d5-4e6e-97c6-6081558bb263","emotionId":"f7ce1053-2001-4b91-980e-80208645e976","italic":false},{"id":"4e9b8e39-326e-590e-aef8-2fcaca4f6880","text":"Близость к людям не поможет, если тебя не назначат.","characterId":"c15323c4-79bc-4b5d-868f-fff59ea61a0b","emotionId":"fdf2ff59-2e09-59fc-a1ba-d3f557781c3a","italic":false},{"id":"3087a4d5-bfb2-540c-b50a-88d6463ac3f7","text":"Зоя понимала: её поддержка не закончила спор, а определила, кому придётся доказывать правоту.","characterId":"","emotionId":"","italic":false}],"route":{"next":"498813db-8e8a-5dc6-a2c1-498a3a0b62f1","statId":"","operator":">=","value":0,"yes":"","no":""},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[]},{"id":"ab8a862d-b0f7-55dc-881f-7855e69e17af","name":"Требование плана","backgroundId":"e2fb766b-c8a2-525b-8404-50c91eb3ed1e","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","text":"Я поддержу не имя на карточке, а план. Сначала покажите, как собираетесь работать вместе.","italic":false,"lines":[{"id":"b0dfc091-ff7a-5f03-b7a2-04d7f7648f53","text":"Я отвечу за коллектив и работу магазина.","characterId":"92f40577-c7d5-4e6e-97c6-6081558bb263","emotionId":"f7ce1053-2001-4b91-980e-80208645e976","italic":false},{"id":"b3b6b104-3e65-5cae-80eb-b648fb477fe7","text":"А я — за разговор с руководством. Но вопрос должности мы ещё обсудим.","characterId":"c15323c4-79bc-4b5d-868f-fff59ea61a0b","emotionId":"fdf2ff59-2e09-59fc-a1ba-d3f557781c3a","italic":false},{"id":"80aadf76-67e5-57e6-9e75-14145300353b","text":"Обе были недовольны, однако впервые заговорили об обязанностях вместо кресла.","characterId":"","emotionId":"","italic":false}],"route":{"next":"498813db-8e8a-5dc6-a2c1-498a3a0b62f1","statId":"","operator":">=","value":0,"yes":"","no":""},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[]},{"id":"498813db-8e8a-5dc6-a2c1-498a3a0b62f1","name":"Завтра начинаем","backgroundId":"e2fb766b-c8a2-525b-8404-50c91eb3ed1e","characterId":"","emotionId":"","text":"Наталья оставила карточку «Заведующий» пустой и вернула её на доску.","italic":false,"lines":[{"id":"e031af2f-6c05-5fdf-a4c0-9315de8a6b04","text":"Хорошо. Имя впишем позже.","characterId":"c15323c4-79bc-4b5d-868f-fff59ea61a0b","emotionId":"fdf2ff59-2e09-59fc-a1ba-d3f557781c3a","italic":false},{"id":"79a311e9-9b6d-5b80-a472-9fb55fe78bed","text":"Зоя посмотрела на линии, фотографию магазина и оставшиеся звёздочки.","characterId":"","emotionId":"","italic":false},{"id":"7f349902-fe00-5fdc-88ed-238c73222f2a","text":"А что мы делаем сейчас?","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","italic":false},{"id":"48ab299f-8c5f-5823-a66e-eef7a7d355ef","text":"С. С. закрыла папку и выключила свет над столом.","characterId":"","emotionId":"","italic":false},{"id":"be2d0372-aa7f-54c6-9125-916967edb934","text":"Завтра начинаем.","characterId":"c15323c4-79bc-4b5d-868f-fff59ea61a0b","emotionId":"fdf2ff59-2e09-59fc-a1ba-d3f557781c3a","italic":false}],"route":{"next":"","statId":"","operator":">=","value":0,"yes":"","no":""},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[]}]};
